fn frame(t: i32) {
    let pal = [0xff5050, 0x50ff80, 0x50a0ff, 0xffd050];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut k: i32 = 0;
        while k < 4 {
            host::display::state_set(8 + k * 4, 30 + k * 40);
            host::display::state_set(9 + k * 4, 30 + k * 25);
            host::display::state_set(10 + k * 4, 2 + k);
            host::display::state_set(11 + k * 4, 3 - k % 3);
            k = k + 1;
        }
    }
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 4 {
        let size: i32 = 12 + i * 6;
        let mut x: i32 = host::display::state_get(8 + i * 4);
        let mut y: i32 = host::display::state_get(9 + i * 4);
        let mut vx: i32 = host::display::state_get(10 + i * 4);
        let mut vy: i32 = host::display::state_get(11 + i * 4);
        x = x + vx;
        y = y + vy;
        if x < 0 { x = 0; vx = 0 - vx; }
        if x > w - size { x = w - size; vx = 0 - vx; }
        if y < 0 { y = 0; vy = 0 - vy; }
        if y > h - size { y = h - size; vy = 0 - vy; }
        host::display::state_set(8 + i * 4, x);
        host::display::state_set(9 + i * 4, y);
        host::display::state_set(10 + i * 4, vx);
        host::display::state_set(11 + i * 4, vy);
        host::display::fill_rect(x, y, size, size, pal[i]);
        i = i + 1;
    }
    host::display::present();
}
